1	const PROCESSING_FEE = 5;
2	const FIRST_INSURANCE_RATE = 0.1;
3	const DEDUCTIBLE = 100;
4	const CAP_MULTIPLIER = 2;
5	
6	interface CatalogEntry {
7	  basePremium: number;
8	  insuranceValue: number;
9	}
10	
11	const CATALOG: Record<string, CatalogEntry> = {
12	  sword: { basePremium: 100, insuranceValue: 1000 },
13	  amulet: { basePremium: 60, insuranceValue: 600 },
14	  staff: { basePremium: 80, insuranceValue: 800 },
15	  potion: { basePremium: 40, insuranceValue: 400 },
16	  rune: { basePremium: 25, insuranceValue: 250 },
17	  moonstone: { basePremium: 25, insuranceValue: 250 },
18	};
19	
20	const basePremiumOf = (type: string): number => CATALOG[type]?.basePremium ?? 0;
21	const insuranceValueOf = (type: string): number => CATALOG[type]?.insuranceValue ?? 0;
22	
23	const sumBy = <T>(items: readonly T[], value: (item: T) => number): number =>
24	  items.reduce((total, item) => total + value(item), 0);
25	
26	interface Item {
27	  type: string;
28	  material?: string;
29	  enchantment?: number;
30	  cursed?: boolean;
31	}
32	
33	const HIGH_ENCHANTMENT_PREMIUM_THRESHOLD = 5;
34	
35	const enchantmentOf = (item: Item): number => item.enchantment ?? 0;
36	
37	const isCursed = (item: Item): boolean => item.cursed === true;
38	const hasHighEnchantmentForPremium = (item: Item): boolean =>
39	  enchantmentOf(item) >= HIGH_ENCHANTMENT_PREMIUM_THRESHOLD;
40	
41	const SURCHARGE_RATES: ReadonlyArray<{ applies: (item: Item) => boolean; rate: number }> = [
42	  { applies: isCursed, rate: 0.5 },
43	  { applies: hasHighEnchantmentForPremium, rate: 0.3 },
44	];
45	
46	const itemSurcharge = (item: Item): number =>
47	  basePremiumOf(item.type) *
48	  sumBy(SURCHARGE_RATES, ({ applies, rate }) => (applies(item) ? rate : 0));
49	
50	const itemsSurcharge = (items: Item[]): number => sumBy(items, itemSurcharge);
51	
52	interface QuoteStep {
53	  op: "quote";
54	  items: Item[];
55	}
56	
57	interface Damage {
58	  itemType: string;
59	  amount: number;
60	}
61	
62	interface ClaimStep {
63	  op: "claim";
64	  policy: number;
65	  incident: {
66	    cause: string;
67	    damages: Damage[];
68	  };
69	}
70	
71	type Step = QuoteStep | ClaimStep;
72	
73	interface Customer {
74	  yearsWithMHPCO: number;
75	}
76	
77	interface Scenario {
78	  customer: Customer;
79	  steps: Step[];
80	}
81	
82	interface QuoteResult {
83	  premium: number;
84	}
85	
86	interface ClaimResult {
87	  payout: number;
88	  remainingCap: number;
89	}
90	
91	type StepResult = QuoteResult | ClaimResult;
92	
93	interface ScenarioResult {
94	  results: StepResult[];
95	}
96	
97	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
98	const COMPONENT_BLOCK_SIZE = 3;
99	const COMPONENT_BLOCK_BASE = 60;
100	
101	const roundUpInMHPCOsFavor = (amount: number): number => Math.ceil(amount);
102	const roundDownInMHPCOsFavor = (amount: number): number => Math.floor(amount);
103	
104	const countItemsByType = (items: Item[]): Array<[string, number]> => {
105	  const counts = new Map<string, number>();
106	  for (const item of items) {
107	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
108	  }
109	  return [...counts];
110	};
111	
112	const groupBasePremium = (type: string, count: number): number => {
113	  if (COMPONENT_TYPES.has(type) && count === COMPONENT_BLOCK_SIZE) {
114	    return COMPONENT_BLOCK_BASE;
115	  }
116	  return basePremiumOf(type) * count;
117	};
118	
119	const itemsBasePremium = (items: Item[]): number =>
120	  sumBy(countItemsByType(items), ([type, count]) => groupBasePremium(type, count));
121	
122	const firstInsuranceSurcharge = (base: number): number => base * FIRST_INSURANCE_RATE;
123	
124	const LOYALTY_YEARS_THRESHOLD = 2;
125	const LOYALTY_DISCOUNT_RATE = 0.2;
126	
127	const isLoyalCustomer = (customer: Customer): boolean =>
128	  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD;
129	
130	const loyaltyDiscount = (customer: Customer, base: number): number =>
131	  isLoyalCustomer(customer) ? base * LOYALTY_DISCOUNT_RATE : 0;
132	
133	const quotePremium = ({ items }: QuoteStep, customer: Customer): number => {
134	  const base = itemsBasePremium(items);
135	  const premiumBeforeFee =
136	    base + itemsSurcharge(items) + firstInsuranceSurcharge(base) - loyaltyDiscount(customer, base);
137	  return roundUpInMHPCOsFavor(premiumBeforeFee + PROCESSING_FEE);
138	};
139	
140	interface Policy {
141	  items: Item[];
142	  remainingCap: number;
143	}
144	
145	const createPolicy = (step: QuoteStep): Policy => ({
146	  items: step.items,
147	  remainingCap: sumBy(step.items, (item) => insuranceValueOf(item.type)) * CAP_MULTIPLIER,
148	});
149	
150	const HIGH_ENCHANTMENT_REIMBURSEMENT_RATE = 0.5;
151	const FULL_REIMBURSEMENT_RATE = 1;
152	const HIGH_ENCHANTMENT_CLAIM_THRESHOLD = 8;
153	
154	const hasHighEnchantmentForClaim = (item: Item): boolean =>
155	  enchantmentOf(item) >= HIGH_ENCHANTMENT_CLAIM_THRESHOLD;
156	
157	const reimbursementRate = (item: Item): number =>
158	  hasHighEnchantmentForClaim(item) ? HIGH_ENCHANTMENT_REIMBURSEMENT_RATE : FULL_REIMBURSEMENT_RATE;
159	
160	const damagePayout = (damage: Damage, item: Item): number =>
161	  Math.max(0, damage.amount * reimbursementRate(item) - DEDUCTIBLE);
162	
163	const findItem = (policy: Policy, itemType: string): Item =>
164	  policy.items.find((item) => item.type === itemType)!;
165	
166	const calculatePayout = (damages: Damage[], policy: Policy): number => {
167	  const rawPayout = sumBy(damages, (damage) => damagePayout(damage, findItem(policy, damage.itemType)));
168	  return roundDownInMHPCOsFavor(Math.min(rawPayout, policy.remainingCap));
169	};
170	
171	const processClaim = (step: ClaimStep, policies: Map<number, Policy>): ClaimResult => {
172	  const policy = policies.get(step.policy)!;
173	  const payout = calculatePayout(step.incident.damages, policy);
174	  policy.remainingCap -= payout;
175	  return { payout, remainingCap: policy.remainingCap };
176	};
177	
178	const processQuote = (
179	  step: QuoteStep,
180	  customer: Customer,
181	  policies: Map<number, Policy>,
182	): QuoteResult => {
183	  policies.set(policies.size, createPolicy(step));
184	  return { premium: quotePremium(step, customer) };
185	};
186	
187	const processStep = (
188	  step: Step,
189	  customer: Customer,
190	  policies: Map<number, Policy>,
191	): StepResult =>
192	  step.op === "quote"
193	    ? processQuote(step, customer, policies)
194	    : processClaim(step, policies);
195	
196	export const runScenario = ({ customer, steps }: Scenario): ScenarioResult => {
197	  const policies = new Map<number, Policy>();
198	  const results = steps.map((step) => processStep(step, customer, policies));
199	  return { results };
200	};
